#include <cstdio>
#include <iostream>
#include <algorithm>
#include <vector>

using namespace std;

const int N = 1e6 + 10;
typedef pair<int, int> PII;
PII items[N];
#define a first
#define b second

int main() {
    int n;
    cin >> n;
    for(int i = 0; i < n; i++) {
       cin >> items[i].a;
    }
    for(int i = 0; i < n; i++) {
       cin >> items[i].b;
    }

    sort(items, items + n);

    int special = 0, normal = 0;
    for(int i = n - 1; i >= 0; i--) {
        if (special + items[i].a >= normal + items[i].b) {
            special += items[i].a;
            normal += items[i].b;
        } else break;
    }

    cout << special << endl;
    return 0;
}
```
