### Java

```java
import java.util.Arrays;
import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int[] p = new int[n];
        int[] q = new int[n];

        for (int i = 0; i < n; i++) {
            p[i] = sc.nextInt();
        }
        for (int i = 0; i < n; i++) {
            q[i] = sc.nextInt();
        }

        // 将原料信息存入二维数组，每行 {精华, 杂质}
        int[][] items = new int[n][2];
        for (int i = 0; i < n; i++) {
            items[i][0] = p[i];
            items[i][1] = q[i];
        }

        // 按精华份数降序排序
        Arrays.sort(items, (a, b) -> Integer.compare(b[0], a[0]));

        int sumP = 0, sumQ = 0;
        for (int i = 0; i < n; i++) {
            int pi = items[i][0];
            int qi = items[i][1];
            if (sumP + pi >= sumQ + qi) {
                sumP += pi;
                sumQ += qi;
            } else {
                break;
            }
        }

        System.out.println(sumP);
    }
}
```

### C++

```cpp
#include <iostream>
#include <vector>
#include <algorithm>

using namespace std;

int main() {
    int n;
    cin >> n;
    vector<int> p(n), q(n);
    for (int i = 0; i < n; ++i) cin >> p[i];
    for (int i = 0; i < n; ++i) cin >> q[i];

    // 将每种原料的精华和杂质组合，并按精华份数降序排序
    vector<pair<int, int>> items(n);
    for (int i = 0; i < n; ++i) {
        items[i] = {p[i], q[i]};
    }
    sort(items.begin(), items.end(),
         [](const pair<int, int>& a, const pair<int, int>& b) {
             return a.first > b.first;  // 精华降序
         });

    int sum_p = 0, sum_q = 0;
    for (const auto& item : items) {
        int pi = item.first, qi = item.second;
        if (sum_p + pi >= sum_q + qi) {
            sum_p += pi;
            sum_q += qi;
        } else {
            break;
        }
    }

    cout << sum_p << endl;
    return 0;
}
